import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/auth/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/auth/SignupPage" with { type: "ref" };
import { getTickets, getAgents } from "./src/queries" with { type: "ref" };
import { createTicket, simulateSlaBreach } from "./src/actions" with { type: "ref" };
import { userSignupFields } from "./src/auth/signup" with { type: "ref" };
import { seedData } from "./src/seeds" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {
        userSignupFields,
      },
    },
    onAuthFailedRedirectTo: "/login",
    onAuthSucceededRedirectTo: "/",
  },
  db: {
    seeds: [seedData],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getTickets, { entities: ["Ticket"] }),
    query(getAgents, { entities: ["User", "Ticket"] }),
    action(createTicket, { entities: ["Ticket", "User"] }),
    action(simulateSlaBreach, { entities: ["Ticket", "User"] }),
  ],
});

import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  username: async (data: any) => {
    if (!data.username) {
      throw new Error("Username is required");
    }
    return data.username;
  },
  password: async (data: any) => {
    // Standard password field is handled by Wasp's auth backend.
    // In order to populate the password field on the User model, we'll store a dummy or plain password if provided.
    return data.password || "password123";
  },
  role: async (data: any) => {
    return data.role || "CUSTOMER";
  }
});

import type { PrismaClient } from "@prisma/client";
import { createProviderId, sanitizeAndSerializeProviderData, createUser } from "wasp/server/auth";

export const seedData = async (prisma: PrismaClient) => {
  // Clear existing data
  await prisma.ticket.deleteMany({});
  await prisma.authIdentity.deleteMany({});
  await prisma.session.deleteMany({});
  await prisma.auth.deleteMany({});
  await prisma.user.deleteMany({});

  // Seed manager
  const managerProviderId = createProviderId("username", "manager");
  const managerProviderData = await sanitizeAndSerializeProviderData<"username">({
    hashedPassword: "password123",
  });
  await createUser(managerProviderId, managerProviderData, {
    username: "manager",
    password: "password123",
    role: "MANAGER",
  });

  // Seed agents
  const agent1ProviderId = createProviderId("username", "agent1");
  const agent1ProviderData = await sanitizeAndSerializeProviderData<"username">({
    hashedPassword: "password123",
  });
  await createUser(agent1ProviderId, agent1ProviderData, {
    username: "agent1",
    password: "password123",
    role: "AGENT",
  });

  const agent2ProviderId = createProviderId("username", "agent2");
  const agent2ProviderData = await sanitizeAndSerializeProviderData<"username">({
    hashedPassword: "password123",
  });
  await createUser(agent2ProviderId, agent2ProviderData, {
    username: "agent2",
    password: "password123",
    role: "AGENT",
  });

  // Seed customer
  const customer1ProviderId = createProviderId("username", "customer1");
  const customer1ProviderData = await sanitizeAndSerializeProviderData<"username">({
    hashedPassword: "password123",
  });
  await createUser(customer1ProviderId, customer1ProviderData, {
    username: "customer1",
    password: "password123",
    role: "CUSTOMER",
  });

  console.log("Database seeded successfully!");
};

import type { GetTickets, GetAgents } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const getTickets: GetTickets<void, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Ticket.findMany({
    include: {
      assignee: true,
      creator: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });
};

export const getAgents: GetAgents<void, any[]> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const agents = await context.entities.User.findMany({
    where: {
      role: "AGENT",
    },
    include: {
      assignedTickets: {
        where: {
          status: {
            not: "RESOLVED",
          },
        },
      },
    },
    orderBy: {
      id: "asc",
    },
  });

  return agents.map((agent) => ({
    id: agent.id,
    username: agent.username,
    role: agent.role,
    workload: agent.assignedTickets.length,
  }));
};

import type { CreateTicket, SimulateSlaBreach } from "wasp/server/operations";
import { HttpError } from "wasp/server";

export const createTicket: CreateTicket<
  { title: string; description: string; priority: "HIGH" | "MEDIUM" | "LOW" },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const now = new Date();
  let seconds = 0;
  if (args.priority === "HIGH") {
    seconds = 3600;
  } else if (args.priority === "MEDIUM") {
    seconds = 14400;
  } else if (args.priority === "LOW") {
    seconds = 86400;
  } else {
    throw new HttpError(400, "Invalid priority");
  }

  const slaDeadline = new Date(now.getTime() + seconds * 1000);

  // Find lowest workload agent
  const agents = await context.entities.User.findMany({
    where: {
      role: "AGENT",
    },
    include: {
      assignedTickets: {
        where: {
          status: {
            not: "RESOLVED",
          },
        },
      },
    },
  });

  let assigneeId: number | null = null;
  if (agents.length > 0) {
    const agentsWithWorkload = agents.map((agent) => ({
      id: agent.id,
      workload: agent.assignedTickets.length,
    }));

    agentsWithWorkload.sort((a, b) => {
      if (a.workload !== b.workload) {
        return a.workload - b.workload;
      }
      return a.id - b.id;
    });

    assigneeId = agentsWithWorkload[0].id;
  }

  return context.entities.Ticket.create({
    data: {
      title: args.title,
      description: args.description,
      priority: args.priority,
      slaDeadline,
      creatorId: context.user.id,
      assigneeId,
    },
    include: {
      assignee: true,
      creator: true,
    },
  });
};

export const simulateSlaBreach: SimulateSlaBreach<
  { ticketId: number },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const ticket = await context.entities.Ticket.findUnique({
    where: { id: args.ticketId },
  });

  if (!ticket) {
    throw new HttpError(404, "Ticket not found");
  }

  const twoHoursInMs = 2 * 60 * 60 * 1000;
  const newCreatedAt = new Date(ticket.createdAt.getTime() - twoHoursInMs);
  const newSlaDeadline = new Date(ticket.slaDeadline.getTime() - twoHoursInMs);

  let updatedTicket = await context.entities.Ticket.update({
    where: { id: args.ticketId },
    data: {
      createdAt: newCreatedAt,
      slaDeadline: newSlaDeadline,
    },
  });

  if (newSlaDeadline < new Date() && updatedTicket.status !== "RESOLVED" && !updatedTicket.isEscalated) {
    const managers = await context.entities.User.findMany({
      where: { role: "MANAGER" },
      orderBy: { id: "asc" },
    });

    let assigneeIdToSet = updatedTicket.assigneeId;
    if (managers.length > 0) {
      assigneeIdToSet = managers[0].id;
    }

    updatedTicket = await context.entities.Ticket.update({
      where: { id: args.ticketId },
      data: {
        isEscalated: true,
        assigneeId: assigneeIdToSet,
      },
      include: {
        assignee: true,
        creator: true,
      },
    });
  } else {
    updatedTicket = await context.entities.Ticket.findUnique({
      where: { id: args.ticketId },
      include: {
        assignee: true,
        creator: true,
      },
    }) as any;
  }

  return updatedTicket;
};

